/**
 * Changes the workspace's URL slug (ADR 0005). A rename to the current slug
 * is a no-op: nothing changes, nothing is published. Otherwise the new slug
 * must pass the shared slug rules and be available — unavailable slugs are
 * refused with the same `InvalidSlugError` a malformed slug gets, never
 * suffixed, because a rename is a deliberate choice rather than a derivation.
 * The slug being replaced is retired for `ORG_SLUG_HOLD_DAYS` days rather
 * than released, so old links keep resolving for a while.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (input.slug === org.slug) return org;

  assertValidSlug(input.slug);

  const unavailable =
    (await orgRepo.isSlugCurrentForAnotherOrg(input.orgId, input.slug)) ||
    (await orgRepo.isSlugRetiredByAnotherOrg(input.orgId, input.slug));

  if (unavailable) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const renamed = await orgRepo.renameOrgSlug(input.orgId, org.slug, input.slug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: org.slug,
    to: input.slug,
  });

  return renamed;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */

