import { describe, expect, it, beforeAll, afterAll } from "vitest";
import { createTenant, useTemporaryDatabase } from "../../tests/server/_support/fixtures";
import * as orgService from "@/server/services/organization-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("rename sanity", () => {
  it("full lifecycle", async () => {
    const t1 = await createTenant("rename-a");
    const t2 = await createTenant("rename-b");

    const events: any[] = [];
    const off = subscribe("organization.slug_changed", (p) => events.push(p));

    // no-op
    const same = await orgService.renameOrganizationSlug(t1.actors.owner, {
      orgId: t1.org.id,
      slug: "rename-a",
    });
    expect(same.slug).toBe("rename-a");
    expect(events.length).toBe(0);

    // actual rename
    const renamed = await orgService.renameOrganizationSlug(t1.actors.owner, {
      orgId: t1.org.id,
      slug: "rename-a-new",
    });
    expect(renamed.slug).toBe("rename-a-new");
    expect(events.length).toBe(1);
    expect(events[0]).toMatchObject({ from: "rename-a", to: "rename-a-new" });

    // old slug still resolves
    const viaOld = await orgRepo.findOrgBySlug("rename-a");
    expect(viaOld?.id).toBe(t1.org.id);
    expect(viaOld?.slug).toBe("rename-a-new");

    // other org cannot claim the retired slug
    await expect(
      orgService.renameOrganizationSlug(t2.actors.owner, {
        orgId: t2.org.id,
        slug: "rename-a",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    // other org cannot claim the CURRENT slug either
    await expect(
      orgService.renameOrganizationSlug(t2.actors.owner, {
        orgId: t2.org.id,
        slug: "rename-a-new",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    // non-owner (admin lacks org:update? admin role rank >= admin required, admin passes)
    // viewer should be denied
    await expect(
      orgService.renameOrganizationSlug(t1.actors.viewer, {
        orgId: t1.org.id,
        slug: "rename-a-again",
      }),
    ).rejects.toThrow();

    // self can reclaim its own retired slug even mid-hold
    const reclaimed = await orgService.renameOrganizationSlug(t1.actors.owner, {
      orgId: t1.org.id,
      slug: "rename-a",
    });
    expect(reclaimed.slug).toBe("rename-a");
    expect(events.length).toBe(2);

    // now "rename-a-new" should be retired, and resolve back to t1
    const viaChain = await orgRepo.findOrgBySlug("rename-a-new");
    expect(viaChain?.id).toBe(t1.org.id);

    // and "rename-a" is no longer in the retired table for t1 (un-retired)
    // verify by having t2 try to take "rename-a" now — should still fail (current slug of t1)
    await expect(
      orgService.renameOrganizationSlug(t2.actors.owner, {
        orgId: t2.org.id,
        slug: "rename-a",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    off();
  });
});
EOF
